import{_t as e,it as t,n,rt as r}from"./chunks/framework.C1oW5ckO.js";var i=JSON.parse(`{"title":"Maintaining Static Hermes WASI support","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/tools/static-hermes-runtime/docs/maintaining-wasi.md"},"headers":[],"relativePath":"tools/static-hermes-runtime/docs/maintaining-wasi.md","filePath":"tools/static-hermes-runtime/docs/maintaining-wasi.md","lastUpdated":1792029942000}`),a={name:`tools/static-hermes-runtime/docs/maintaining-wasi.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="maintaining-static-hermes-wasi-support" tabindex="-1">Maintaining Static Hermes WASI support <a class="header-anchor" href="#maintaining-static-hermes-wasi-support" aria-label="Permalink to “Maintaining Static Hermes WASI support”">​</a></h1><p>This guide is for maintainers who change the locked WASI definitions, capability bundles, or native adapters. Plugin developers should use the <a href="./wasi">WASI guide</a> for imports, permissions, resource ownership, and runtime limits.</p><h2 id="source-files" tabindex="-1">Source files <a class="header-anchor" href="#source-files" aria-label="Permalink to “Source files”">​</a></h2><table tabindex="0"><thead><tr><th>Concern</th><th>Source</th></tr></thead><tbody><tr><td>Capability names and interface expansion</td><td><a href="../../build/src/capabilities.ts"><code>tools/build/src/capabilities.ts</code></a></td></tr><tr><td>WASI version, WIT files, hashes, source URLs, and generated WIT files</td><td><a href="../../build/wasi-wit.lock.json"><code>tools/build/wasi-wit.lock.json</code></a></td></tr><tr><td>WIT download, SHA-256 verification, and versioned cache</td><td><a href="../../build/src/wasi-wit.ts"><code>tools/build/src/wasi-wit.ts</code></a></td></tr><tr><td>Plugin-world imports and WIT file preparation</td><td><a href="../../build/src/wit.ts"><code>tools/build/src/wit.ts</code></a></td></tr><tr><td>TypeScript declarations from the prepared world</td><td><a href="../../build/src/types.ts"><code>tools/build/src/types.ts</code></a></td></tr><tr><td>TypeScript call analysis for used Pumpkin and WASI methods</td><td><a href="../../build/src/wit-method-usage.ts"><code>tools/build/src/wit-method-usage.ts</code></a></td></tr><tr><td><code>wasm-tools</code> input and WIT parser</td><td><a href="../src/wit/parser.ts"><code>src/wit/parser.ts</code></a></td></tr><tr><td>Dependency aliases and resolved WIT types</td><td><a href="../src/wit/resolver.ts"><code>src/wit/resolver.ts</code></a></td></tr><tr><td>Used methods, feature closure, event fields, and adapter plans</td><td><a href="../src/wit/analysis.ts"><code>src/wit/analysis.ts</code></a></td></tr><tr><td>JavaScript facades and native adapter emission</td><td><a href="../src/wit/emitters.ts"><code>src/wit/emitters.ts</code></a></td></tr><tr><td>Runtime shim and API enum generation</td><td><a href="../src/wit/generation.ts"><code>src/wit/generation.ts</code></a></td></tr><tr><td>Hermes source checkout, patches, build profiles, cache, and artifacts</td><td><a href="../src/hermes/prepare.ts"><code>src/hermes/prepare.ts</code></a></td></tr><tr><td>Component analysis, bindings, bytecode compilation, and linking</td><td><a href="../src/component/build.ts"><code>src/component/build.ts</code></a></td></tr></tbody></table><h2 id="add-or-upgrade-an-interface" tabindex="-1">Add or upgrade an interface <a class="header-anchor" href="#add-or-upgrade-an-interface" aria-label="Permalink to “Add or upgrade an interface”">​</a></h2><ol><li>Confirm that the target Pumpkin runtime can provide the interface and that its WIT/API version is compatible.</li><li>Add or update the pinned files and hashes in <code>tools/build/wasi-wit.lock.json</code>. Keep alternate source URLs there; the WASI HTTP definitions use the <code>wasi-http</code> source recorded by the lock.</li><li>Add the interface to a bundle in <code>tools/build/src/capabilities.ts</code> with its required dependencies. Keep shared imports deduplicated.</li><li>Check that selected feature-gated operations enable their required <code>wit-bindgen</code> feature. The build derives these features from the selected operations.</li><li>Confirm that the Static Hermes converter supports the WIT parameter and result types. Unsupported operations fail with a missing-adapter diagnostic; extend conversion and ownership cleanup where needed.</li><li>Update adapter fixtures and coverage. The <a href="../test/wit-api-coverage.test.mjs"><code>wit-api-coverage</code> test</a> checks that the generator can plan and emit adapters for every operation in the locked interfaces. The WASI WIT tests cover imports, dependency resolution, resource handling, and feature selection.</li><li>Verify the imports and permissions on the target Pumpkin server. Adapter-generation checks do not prove that a server provides an import or implements an operation as expected.</li></ol><p>Keep the pinned <code>@pumpkin-plugins/pumpkin-api</code> version aligned with the Pumpkin server plugin ABI, as described in <a href="/pumpkin-plugins/guides/building">Building</a>. WASI has its own lock and host compatibility requirements.</p>`,7)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};